from __future__ import annotations

import math
from numbers import Real
from pathlib import Path


def _numeric_observation_state(value: object) -> tuple[int, bool]:
    if isinstance(value, bool):
        return 0, True
    if isinstance(value, Real):
        finite = math.isfinite(float(value))
        return int(finite), finite
    if isinstance(value, dict):
        states = [_numeric_observation_state(item) for item in value.values()]
    elif isinstance(value, (list, tuple)):
        states = [_numeric_observation_state(item) for item in value]
    else:
        return 0, True
    return sum(count for count, _ in states), all(finite for _, finite in states)


def aggregate_public_reports(reports: list[dict]) -> dict:
    observation_count, all_finite = _numeric_observation_state(reports)
    return {
        "case_count": len(reports),
        "finite_observation_count": observation_count,
        "cases": reports,
        "complete": bool(reports) and observation_count > 0 and all_finite,
